-- =====================================================================
-- Proyecto final: Análisis de ventas de un retail multinacional
-- Carga del modelo limpio en PostgreSQL
-- Origen: data/clean/sales_clean.csv (salida del ETL en PySpark)
-- Uso:  psql -U postgres -d <base_de_datos> -f postgresql/modelo_retail.sql
--       (o abrir y ejecutar en pgAdmin > Query Tool)
-- Se puede ejecutar varias veces: borra y vuelve a crear el esquema.
-- =====================================================================
SET client_encoding = 'UTF8';
BEGIN;

DROP SCHEMA IF EXISTS retail CASCADE;
CREATE SCHEMA retail;
SET search_path TO retail;

-- ---------------------------------------------------------------------
-- 1. Tabla plana con los datos limpios (tal como salen del ETL)
-- ---------------------------------------------------------------------
CREATE TABLE ventas_limpias (
    order_number INTEGER,
    quantity_ordered INTEGER,
    price_each NUMERIC(12,2),
    order_line_number INTEGER,
    sales NUMERIC(14,2),
    order_timestamp DATE,
    status VARCHAR(100),
    source_quarter_id INTEGER,
    source_month_id INTEGER,
    source_year_id INTEGER,
    product_line VARCHAR(100),
    msrp NUMERIC(12,2),
    product_code VARCHAR(100),
    customer_name VARCHAR(100),
    phone VARCHAR(100),
    address_line_1 VARCHAR(100),
    address_line_2 VARCHAR(100),
    city VARCHAR(100),
    state VARCHAR(100),
    postal_code VARCHAR(100),
    country VARCHAR(100),
    territory VARCHAR(100),
    contact_last_name VARCHAR(100),
    contact_first_name VARCHAR(100),
    deal_size VARCHAR(100),
    invalid_order_number BOOLEAN,
    invalid_order_line_number BOOLEAN,
    invalid_quantity BOOLEAN,
    invalid_price_each BOOLEAN,
    invalid_sales BOOLEAN,
    invalid_order_date BOOLEAN,
    invalid_msrp BOOLEAN,
    has_quality_error BOOLEAN,
    es_venta_realizada BOOLEAN,
    order_date DATE,
    year INTEGER,
    month INTEGER,
    quarter INTEGER,
    discount_pct NUMERIC(8,4),
    estimated_cost NUMERIC(14,2),
    profit NUMERIC(14,2),
    margin_pct NUMERIC(8,4),
    PRIMARY KEY (order_number, order_line_number)
);







-- ---------------------------------------------------------------------
-- 2. Modelo estrella
-- ---------------------------------------------------------------------
CREATE TABLE dim_producto (
    product_code VARCHAR(20) PRIMARY KEY,
    product_line VARCHAR(50) NOT NULL,
    msrp         NUMERIC(12,2)
);

CREATE TABLE dim_cliente (
    cliente_id         SERIAL PRIMARY KEY,
    customer_name      VARCHAR(100) NOT NULL UNIQUE,
    contact_first_name VARCHAR(50),
    contact_last_name  VARCHAR(50),
    phone              VARCHAR(30),
    address_line_1     VARCHAR(100),
    address_line_2     VARCHAR(100),
    city               VARCHAR(50),
    state              VARCHAR(50),
    postal_code        VARCHAR(20),
    country            VARCHAR(50),
    territory          VARCHAR(20)
);

CREATE TABLE dim_fecha (
    fecha       DATE PRIMARY KEY,
    anio        INTEGER NOT NULL,
    trimestre   INTEGER NOT NULL,
    mes         INTEGER NOT NULL,
    nombre_mes  VARCHAR(15) NOT NULL,
    dia         INTEGER NOT NULL,
    dia_semana  INTEGER NOT NULL  -- 1 = lunes ... 7 = domingo
);

CREATE TABLE fact_ventas (
    order_number       INTEGER NOT NULL,
    order_line_number  INTEGER NOT NULL,
    fecha              DATE NOT NULL REFERENCES dim_fecha (fecha),
    cliente_id         INTEGER NOT NULL REFERENCES dim_cliente (cliente_id),
    product_code       VARCHAR(20) NOT NULL REFERENCES dim_producto (product_code),
    status             VARCHAR(20) NOT NULL,
    deal_size          VARCHAR(10),
    quantity_ordered   INTEGER NOT NULL,
    price_each         NUMERIC(12,2) NOT NULL,
    sales              NUMERIC(14,2) NOT NULL,
    discount_pct       NUMERIC(8,4),
    estimated_cost     NUMERIC(14,2),
    profit             NUMERIC(14,2),
    margin_pct         NUMERIC(8,4),
    es_venta_realizada BOOLEAN NOT NULL,
    has_quality_error  BOOLEAN NOT NULL,
    PRIMARY KEY (order_number, order_line_number)
);

SELECT DISTINCT product_code, product_line, msrp
FROM ventas_limpias;

                         address_line_1, address_line_2, city, state, postal_code,
                         country, territory)
SELECT DISTINCT customer_name, contact_first_name, contact_last_name, phone,
       address_line_1, address_line_2, city, state, postal_code, country, territory
FROM ventas_limpias
ORDER BY customer_name;

SELECT d::date,
       EXTRACT(YEAR FROM d)::int,
       EXTRACT(QUARTER FROM d)::int,
       EXTRACT(MONTH FROM d)::int,
       (ARRAY['Enero','Febrero','Marzo','Abril','Mayo','Junio','Julio','Agosto',
              'Septiembre','Octubre','Noviembre','Diciembre'])[EXTRACT(MONTH FROM d)::int],
       EXTRACT(DAY FROM d)::int,
       EXTRACT(ISODOW FROM d)::int
FROM generate_series((SELECT MIN(order_date) FROM ventas_limpias),
                     (SELECT MAX(order_date) FROM ventas_limpias),
                     INTERVAL '1 day') AS d;

SELECT v.order_number, v.order_line_number, v.order_date, c.cliente_id, v.product_code,
       v.status, v.deal_size, v.quantity_ordered, v.price_each, v.sales,
       v.discount_pct, v.estimated_cost, v.profit, v.margin_pct,
       v.es_venta_realizada, v.has_quality_error
FROM ventas_limpias v
JOIN dim_cliente c ON c.customer_name = v.customer_name;

CREATE INDEX ix_fact_fecha    ON fact_ventas (fecha);
CREATE INDEX ix_fact_cliente  ON fact_ventas (cliente_id);
CREATE INDEX ix_fact_producto ON fact_ventas (product_code);

COMMIT;

-- ---------------------------------------------------------------------
-- 3. Verificación (debe dar 2823 / 92 / 109 filas)
-- ---------------------------------------------------------------------
SELECT 'ventas_limpias' AS tabla, COUNT(*) AS filas FROM retail.ventas_limpias
UNION ALL SELECT 'fact_ventas',  COUNT(*) FROM retail.fact_ventas
UNION ALL SELECT 'dim_cliente',  COUNT(*) FROM retail.dim_cliente
UNION ALL SELECT 'dim_producto', COUNT(*) FROM retail.dim_producto
UNION ALL SELECT 'dim_fecha',    COUNT(*) FROM retail.dim_fecha;
